import heapq

def match(orders):
    trades = []
    book = {}  # id -> [side, price, qty_remaining, arrival_index, active]
    buy_heap = []  # (-price, arrival_index, id)
    sell_heap = []  # (price, arrival_index, id)
    counter = 0

    def clean_buy():
        while buy_heap:
            negprice, arr, oid = buy_heap[0]
            entry = book.get(oid)
            if entry is None or not entry[4] or entry[2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            entry = book.get(oid)
            if entry is None or not entry[4] or entry[2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            entry = book.get(oid)
            if entry is not None and entry[4] and entry[2] > 0:
                entry[4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        arrival = counter
        counter += 1

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                sp, sarr, soid = sell_heap[0]
                if price is not None and sp > price:
                    break
                sentry = book[soid]
                if not sentry[4] or sentry[2] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                trade_qty = min(remaining, sentry[2])
                trades.append([oid, soid, sp, trade_qty])
                remaining -= trade_qty
                sentry[2] -= trade_qty
                if sentry[2] <= 0:
                    sentry[4] = False
                    heapq.heappop(sell_heap)
                clean_sell()
            if typ == 'limit' and remaining > 0:
                book[oid] = ['buy', price, remaining, arrival, True]
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                if oid in book:
                    pass
                else:
                    book[oid] = ['buy', price if price is not None else 0, 0, arrival, False]

        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                negbp, barr, boid = buy_heap[0]
                bp = -negbp
                if price is not None and bp < price:
                    break
                bentry = book[boid]
                if not bentry[4] or bentry[2] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                trade_qty = min(remaining, bentry[2])
                trades.append([boid, oid, bp, trade_qty])
                remaining -= trade_qty
                bentry[2] -= trade_qty
                if bentry[2] <= 0:
                    bentry[4] = False
                    heapq.heappop(buy_heap)
                clean_buy()
            if typ == 'limit' and remaining > 0:
                book[oid] = ['sell', price, remaining, arrival, True]
                heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                if oid in book:
                    pass
                else:
                    book[oid] = ['sell', price if price is not None else 0, 0, arrival, False]

    return trades

